def test_insert_autostamps_when_no_global_user(db): # noqa
    """Insert with no fields set -> stamps dates and default user."""
    obj = AuditedDummy(name="alpha")
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert isinstance(obj.date_created, datetime)
    assert isinstance(obj.date_updated, datetime)
    assert _is_recent(obj.date_created)
    assert _is_recent(obj.date_updated)
    assert obj.created_by == "default_user"
    assert obj.updated_by == "default_user"


def test_insert_respects_explicit_created_fields(db): # noqa
    """Explicit created fields on insert are kept; updated fields auto-stamped."""
    manual_created = _utc_now() - timedelta(days=10)
    _ensure_user(db, "MANUAL_CREATOR")

    obj = AuditedDummy(
        name="bravo",
        date_created=manual_created,
        created_by="MANUAL_CREATOR",
    )
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert _to_utc(obj.date_created) == _to_utc(manual_created)
    assert obj.created_by == "MANUAL_CREATOR"
    assert isinstance(obj.date_updated, datetime)
    assert obj.date_updated == obj.date_created  # date updated automatically set to date_created value if not provided
    assert obj.updated_by == obj.created_by  # updated_by automatically set to created_by value if not provided


def test_update_overwrites_to_now_and_global_user(db): # noqa
    """
    Current listener behavior on UPDATE:
      - date_updated := now
      - updated_by   := get_default_user_value() (global user or 'default_user')
    """
    obj = AuditedDummy(name="charlie")
    db.add(obj)
    db.commit()
    db.refresh(obj)

    prev_updated = obj.date_updated

    _ensure_user(db, "OTTO")
    set_global_user_id(db, "OTTO")

    obj.name = "charlie-2"
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert obj.updated_by == "OTTO"
    assert obj.date_updated >= prev_updated
    assert _is_recent(obj.date_updated)


def test_update_uses_default_user_when_global_unset(db): # noqa
    """If global user is unset, updated_by falls back to 'default_user'."""
    obj = AuditedDummy(name="echo")
    db.add(obj)
    db.commit()
    db.refresh(obj)

    obj.name = "echo-2"
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert obj.updated_by == "default_user"
    assert _is_recent(obj.date_updated)


def test_insert_autocreates_missing_created_by_user(db): # noqa
    """
    An explicit created_by/updated_by that does not yet exist as an agent is
    auto-created by the before_insert listener (no FK violation, no manual
    pre-creation). This is what lets an admin-token tag load attribute records
    to a named curator on any write endpoint.
    """
    new_uid = "LOADER_NEW_CREATOR"
    # Make sure it does not already exist.
    assert db.query(UserModel).filter_by(automation_username=new_uid).one_or_none() is None

    obj = AuditedDummy(name="foxtrot", created_by=new_uid)
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert obj.created_by == new_uid
    # updated_by mirrors created_by when not supplied (impute_audit_user_ids).
    assert obj.updated_by == new_uid
    # The agent was created as an automation agent.
    user = db.query(UserModel).filter_by(automation_username=new_uid).one_or_none()
    assert user is not None
    assert user.automation_username == new_uid
    assert user.person_id is None


def test_insert_autocreates_distinct_created_and_updated_users(db): # noqa
    """Both created_by and updated_by are auto-created when they differ."""
    creator = "LOADER_CREATOR_X"
    updater = "LOADER_UPDATER_Y"
    for uid in (creator, updater):
        assert db.query(UserModel).filter_by(automation_username=uid).one_or_none() is None

    obj = AuditedDummy(name="golf", created_by=creator, updated_by=updater)
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert obj.created_by == creator
    assert obj.updated_by == updater
    assert db.query(UserModel).filter_by(automation_username=creator).one_or_none() is not None
    assert db.query(UserModel).filter_by(automation_username=updater).one_or_none() is not None


def test_insert_skips_autocreate_for_global_user(db, monkeypatch): # noqa
    """
    Hot-path optimization: when created_by/updated_by resolve to the already-
    ensured global user, its agent id is reused: no label lookup and no
    redundant ON CONFLICT insert (which would burn the agent.id sequence).
    """
    import agr_literature_service.api.models.audited_model as am
    _ensure_user(db, "SPY_GLOBAL")
    set_global_user_id(db, "SPY_GLOBAL")

    calls = []
    orig = am.resolve_agent_id

    def spy(connection, uid): # noqa
        calls.append(uid)
        return orig(connection, uid)

    monkeypatch.setattr(am, "resolve_agent_id", spy)

    # No explicit created_by/updated_by -> both resolve to the global user.
    obj = AuditedDummy(name="india")
    db.add(obj)
    db.commit()
    db.refresh(obj)

    assert obj.created_by == "SPY_GLOBAL"
    assert obj.updated_by == "SPY_GLOBAL"
    assert calls == []  # nothing auto-created; global user already ensured


def test_update_autocreates_missing_updated_by_user(db): # noqa
    """A caller-supplied updated_by on UPDATE is auto-created before the FK check."""
    obj = AuditedDummy(name="hotel")
    db.add(obj)
    db.commit()
    db.refresh(obj)

    new_updater = "LOADER_UPDATER_ON_PATCH"
    assert db.query(UserModel).filter_by(automation_username=new_updater).one_or_none() is None

    obj.name = "hotel-2"
    obj.updated_by = new_updater
